  "g7-1-c1/scientific-notation-digits": {
    "title": "科學記號與位數的判別",
    "chapter": "國一上｜數與數線",
    "section": "指數記法、指數律與科學記號",
    "quizId": "g7-1-c1",
    "topicId": "scientific-notation-digits",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>科學記號與位數的判別</strong>是「指數記法、指數律與科學記號」的核心題型之一。解題時先對照 正負數、數線與絕對值 的觀念：數線向右愈大、向左愈小；相反數代表距離原點相同但方向相反；絕對值只表示距離，所以永遠不小於 0。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
      },
      {
        "type": "formula",
        "content": "|a| = a（a ≥ 0）；|a| = −a（a < 0）\na − b = a + (−b)"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>先圈出每個數前真正的符號</li><li>乘除先判正負，再算絕對值</li><li>加減改寫成加法；同號相加、異號相減</li><li>用估算或數線檢查正負方向</li></ol>"
      },
      {
        "type": "example",
        "q": "例題一：9×10⁵ 是幾位整數？",
        "a": "正確答案：D — 6 位\n1. a×10ⁿ 且 1≤a<10 時，整數位數是 n+1。\n2. 所以 9×10⁵ 是 5+1=6 位整數。"
      },
      {
        "type": "example",
        "q": "例題二：4×10⁷ 是幾位整數？",
        "a": "正確答案：C — 8 位\n1. a×10ⁿ 且 1≤a<10 時，整數位數是 n+1。\n2. 所以 4×10⁷ 是 7+1=8 位整數。"
      },
      {
        "type": "pitfall",
        "html": "<p><strong>易錯：</strong>指數 n 不是位數；位數比 n 多 1。</p><p><strong>快解：</strong>科學記號 a×10ⁿ 的整數位數為 n+1（n 為非負整數）。</p>"
      },
      {
        "type": "text",
        "html": "<p><strong>與小考對應：</strong>章節 g7-1-c1 — 題型 scientific-notation-digits — 變體索引 0–9 由種子碼展開。</p>"
      }
    ]
  },
  "g7-1-c1/scientific-notation-comparison": {
    "title": "科學記號與數的比較大小",
    "chapter": "國一上｜數與數線",
    "section": "指數記法、指數律與科學記號",
    "quizId": "g7-1-c1",
    "topicId": "scientific-notation-comparison",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>科學記號與數的比較大小</strong>是「指數記法、指數律與科學記號」的核心題型之一。解題時先對照 正負數、數線與絕對值 的觀念：數線向右愈大、向左愈小；相反數代表距離原點相同但方向相反；絕對值只表示距離，所以永遠不小於 0。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
      },
      {
        "type": "formula",
        "content": "|a| = a（a ≥ 0）；|a| = −a（a < 0）\na − b = a + (−b)"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>先圈出每個數前真正的符號</li><li>乘除先判正負，再算絕對值</li><li>加減改寫成加法；同號相加、異號相減</li><li>用估算或數線檢查正負方向</li></ol>"
      },
      {
        "type": "example",
        "q": "例題一：比較 2×10⁵ 與 5.3×10⁵ 的大小。",
        "a": "正確答案：B — 2×10⁵ < 5.3×10⁵\n1. 兩數的 10 的次方相同，只要比較前面的係數。\n2. 因為 2<5.3，所以 2×10⁵<5.3×10⁵。"
      },
      {
        "type": "example",
        "q": "例題二：比較 3.6×10⁵ 與 9×10⁵ 的大小。",
        "a": "正確答案：A — 3.6×10⁵ < 9×10⁵\n1. 兩數的 10 的次方相同，只要比較前面的係數。\n2. 因為 3.6<9，所以 3.6×10⁵<9×10⁵。"
      },
      {
        "type": "pitfall",
        "html": "<p><strong>易錯：</strong>不要把係數和指數混在一起加總比較。</p><p><strong>快解：</strong>科學記號比大小：先比 10 的指數；指數相同時比係數。</p>"
      },
      {
        "type": "text",
        "html": "<p><strong>與小考對應：</strong>章節 g7-1-c1 — 題型 scientific-notation-comparison — 變體索引 0–9 由種子碼展開。</p>"
      }
    ]
  },
