        "a": "正確答案：D — 乙\n1. [[frac:3|5]]=0.6，[[frac:5|8]]=0.625；或通分 [[frac:24|40]] 與 [[frac:25|40]]。\n2. [[frac:5|8]] > [[frac:3|5]]，乙較多。"
