        "html": "<p><strong>二元一次式的列式與求值</strong>是「二元一次方程式」的核心題型之一。解題時先對照 二元一次聯立方程式 的觀念：代入法適合某個未知數係數為 1；加減消去法適合係數容易配成相同或相反。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
