        "q": "例題二：地圖比例尺 1：50,000，圖上 3 公分，實際距離多少公里？",
        "a": "正確答案：A — 1.5 公里\n1. 實際 = 3×50000 公分 = 150000。\n2. 換算成公里：1.5 公里。"
