        "type": "text",
        "html": "<p><strong>比與比例式的綜合應用</strong>是「比與比例式」的核心題型之一。解題時先對照 比、比例式與正反比 的觀念：a：b 可寫成 [[frac:a|b]]。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
