        "type": "text",
        "html": "<p><strong>常見多邊形的對角線與對稱軸</strong>是「線對稱與三視圖」的核心題型之一。解題時先對照 幾何基本圖形、角與尺規作圖 的觀念：對頂角相等；互補角和 180°、互餘角和 90°。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
