        "html": "<h4>解題流程</h4><ol><li>根式先分解完全平方因數</li><li>幾何題先找直角與斜邊</li><li>代入平方關係後解非負長度</li><li>用最大邊平方與另兩邊平方和檢查</li></ol>"
