        "type": "text",
        "html": "<p><strong>等腰三角形摺疊的計算</strong>是「三角形和多邊形的內角與外角」的核心題型之一。解題時先對照 三角形性質、全等與尺規 的觀念：三角形任兩邊和大於第三邊；內角和 180°；外角等於兩個不相鄰內角和。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
