        "html": "<p><strong>三角形的邊角關係</strong>是「三角形的邊角關係」的核心題型之一。解題時先對照 三角形性質、全等與尺規 的觀念：三角形任兩邊和大於第三邊；內角和 180°；外角等於兩個不相鄰內角和。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
