        "html": "<p><strong>梯形兩腰中點連線段的問題</strong>是「特殊四邊形與梯形」的核心題型之一。解題時先對照 平行線、四邊形與面積 的觀念：兩平行線被截：同位角、內錯角相等，同側內角互補。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
