        "type": "text",
        "html": "<p><strong>連比例式</strong>是「連比與連比例式」的核心題型之一。解題時先對照 比例線段、縮放與相似形 的觀念：相似判定常用 AA、SAS（夾角相等且夾邊成比例）、SSS。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
