        "html": "<p><strong>圖形旋轉掃過的軌跡或區域</strong>是「圓、圓弧長與扇形」的核心題型之一。解題時先對照 圓、弧、弦與圓周角 的觀念：同弧所對圓周角相等，圓心角是圓周角的 2 倍；直徑所對圓周角為 90°。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
