        "html": "<p><strong>幾何證明常用的性質</strong>是「推理證明」的核心題型之一。解題時先對照 幾何證明與三角形心 的觀念：外心是三邊中垂線交點，到三頂點等距；內心是三角平分線交點，到三邊等距；重心是三中線交點，將中線分成 2:1；垂心是三高交點。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
