        "html": "<p><strong>樹狀圖</strong>是「機率」的核心題型之一。解題時先對照 機率、樣本空間與抽樣 的觀念：等可能情況下，機率=有利結果數÷所有結果數。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
