  "g9-2-c3/plane-plane": {
    "title": "平面與平面",
    "chapter": "國三下｜立體圖形",
    "section": "空間中的線與平面",
    "quizId": "g9-2-c3",
    "topicId": "plane-plane",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>平面與平面</strong>是「空間中的線與平面」的核心題型之一。解題時先對照 立體圖形、表面積與體積 的觀念：柱體體積＝底面積×高；錐體（直圓錐、正角錐）在國中處理展開圖與表面積。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
      },
      {
        "type": "formula",
        "content": "柱體 V＝Bh\n圓柱側面積＝2πrh"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>畫剖面或展開圖</li><li>標底面 B、垂直高 h 與母線 l</li><li>體積與表面積分開計算</li><li>最後檢查平方與立方單位</li></ol>"
      },
      {
        "type": "example",
        "q": "例題一：兩平面永不相交且無限延伸，稱為？",
        "a": "正確答案：D — 平行\n1. 同一空間內無交點 → 平行。"
      },
      {
        "type": "pitfall",
        "html": "<p><strong>易錯：</strong>有交線則相交。</p><p><strong>快解：</strong>平面 // 平面：無交線或重合。</p>"
      },
      {
        "type": "text",
        "html": "<p><strong>與小考對應：</strong>章節 g9-2-c3 — 題型 plane-plane — 變體索引 0–9 由種子碼展開。</p>"
      }
    ]
  },
