  "g9-2-c3/space-distance": {
    "title": "空間中兩點距離的計算",
    "chapter": "國三下｜立體圖形",
    "section": "空間中的線與平面",
    "quizId": "g9-2-c3",
    "topicId": "space-distance",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>空間中兩點距離的計算</strong>是「空間中的線與平面」的核心題型之一。解題時先對照 立體圖形、表面積與體積 的觀念：柱體體積＝底面積×高；錐體（直圓錐、正角錐）在國中處理展開圖與表面積。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
      },
      {
        "type": "formula",
        "content": "柱體 V＝Bh\n圓柱側面積＝2πrh"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>畫剖面或展開圖</li><li>標底面 B、垂直高 h 與母線 l</li><li>體積與表面積分開計算</li><li>最後檢查平方與立方單位</li></ol>"
      },
      {
        "type": "example",
        "q": "例題一：A(1,2,3)、B(4,6,7) 的距離？",
        "a": "正確答案：A — √41\n1. AB=√[(4−1)²+(6−2)²+(7−3)²]=√(9+16+16)=√41。"
      },
      {
        "type": "pitfall",
        "html": "<p><strong>易錯：</strong>先算各軸差再畢氏。</p><p><strong>快解：</strong>空間距離 = √[(Δx)²+(Δy)²+(Δz)²]。</p>"
      },
      {
        "type": "text",
        "html": "<p><strong>與小考對應：</strong>章節 g9-2-c3 — 題型 space-distance — 變體索引 0–9 由種子碼展開。</p>"
      }
    ]
  },
  "g9-2-c3/prism": {
    "title": "角柱",
    "chapter": "國三下｜立體圖形",
    "section": "角柱與圓柱",
    "quizId": "g9-2-c3",
    "topicId": "prism",
    "blocks": [
      {
        "type": "text",
        "html": "<p><strong>角柱</strong>是「角柱與圓柱」的核心題型之一。解題時先對照 立體圖形、表面積與體積 的觀念：柱體體積＝底面積×高；錐體（直圓錐、正角錐）在國中處理展開圖與表面積。</p><p>小考中此題型固定出現 1 題；種子碼決定 10 組凍結變體中的哪一組。</p>"
      },
      {
        "type": "formula",
        "content": "柱體 V＝Bh\n圓柱側面積＝2πrh"
      },
      {
        "type": "text",
        "html": "<h4>解題流程</h4><ol><li>畫剖面或展開圖</li><li>標底面 B、垂直高 h 與母線 l</li><li>體積與表面積分開計算</li><li>最後檢查平方與立方單位</li></ol>"
      },
      {
        "type": "example",
        "q": "例題一：角柱的體積公式？",
        "a": "正確答案：B — 底面積 × 高\n1. V = Bh，B 為底面積，h 為垂直高。"
      },
      {
        "type": "pitfall",
        "html": "<p><strong>易錯：</strong>高要垂直底面。</p><p><strong>快解：</strong>柱體 V = 底面積 × 高。</p>"
      },
      {
        "type": "text",
        "html": "<p><strong>與小考對應：</strong>章節 g9-2-c3 — 題型 prism — 變體索引 0–9 由種子碼展開。</p>"
      }
    ]
  },
